const $ = s => document.querySelector(s);
const st = {site:"all", pc:"all", country:"all", per:6, prob:100};
const FX = {
  rev:"Revenue = sum of invoice values in the period (before tax)",
  gm:"Gross margin = Revenue - Cost of sales",
  gmp:"Gross margin % = Gross margin / Revenue",
  contrib:"Contribution = Gross margin - Direct operating cost",
  cp:"Contribution % = Contribution / Revenue",
  bud:"Budget = planned revenue for the period",
  var:"Budget variance = Revenue - Budget",
  varp:"Variance % = (Revenue - Budget) / Budget",
  dso:"Days sales outstanding = Receivables at period end / (Revenue / days in period)",
  coll:"Collection rate = Cash collected / Revenue",
  sla:"Quote SLA % = Quotes sent within 30 minutes / all quotes",
  conv:"Quote-to-order % = Orders / Quotes",
  wp:"Weighted pipeline = sum of (deal value x stage probability)",
  win:"Win rate = Won deals / (Won + Lost deals)",
  cov:"Pipeline coverage = Open pipeline / (Next-quarter target - Booked)",
  commit:"Commit = Won + Negotiation deals closing in the quarter",
  best:"Best case = Commit + Proposal deals closing in the quarter",
  share:"Market share = Our sales / Market size",
  rel:"Relative share = Our share / Largest competitor's share",
  lost:"Lost market = Market size x (1 - our share) for lines we offer",
  non:"Non-offered market = Market size for lines we do not offer yet",
  tgt:"Draft target = 10% of lost market + 5% of non-offered market (placeholder rates for owner and finance to set)",
  pidx:"Price index = Our average price / Market average price x 100 (100 = at market)",
  rag:"Status: green = meets target; amber = within 10% of target; red = more than 10% off target"
};
const money = v => { const a=Math.abs(v); const s = a>=1e9?(a/1e9).toFixed(2)+"B":a>=1e6?(a/1e6).toFixed(2)+"M":a>=1e3?(a/1e3).toFixed(1)+"k":a.toFixed(0); return (v<0?"-":"")+"$"+s; };
const pct = v => (isFinite(v)? (v*100).toFixed(1):"0.0")+"%";
const sum = (a,f) => a.reduce((t,x)=>t+(f?f(x):x),0);
const esc = s => String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const siteName = id => (D.sites.find(s=>s.id===id)||{}).name||id;
function store(k,v){try{localStorage.setItem("bi."+k,v)}catch(e){}}
function load(k){try{return localStorage.getItem("bi."+k)}catch(e){return null}}
function toast(t){const e=$("#toast");e.textContent=t;e.hidden=false;clearTimeout(e._t);e._t=setTimeout(()=>e.hidden=true,2200)}

/* ---------- filters ---------- */
function months(){return D.months.slice(-st.per)}
function prevMonths(){const n=st.per;const all=D.months;return all.slice(Math.max(0,all.length-2*n),all.length-n)}
function facts(ms){ms=ms||months();return D.facts.filter(f=>(st.site==="all"||f.site===st.site)&&(st.pc==="all"||f.pc===st.pc)&&ms.includes(f.m))}
function deals(){return D.deals.filter(d=>(st.site==="all"||d.site===st.site)&&(st.pc==="all"||d.pc===st.pc)&&(st.country==="all"||d.country===st.country))}
function mkt(){return D.market.filter(m=>(st.site==="all"||m.site===st.site)&&(st.country==="all"||m.country===st.country))}
function fillFilters(){
  $("#sideLbl").textContent=D.label+" · "+D.sites.map(s=>s.name+" ("+s.code+")").join(" · ");
  $("#fSite").innerHTML='<option value="all">All sites on this side</option>'+D.sites.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join("");
  $("#fCountry").innerHTML='<option value="all">All countries</option>'+D.countries.map(c=>`<option>${esc(c)}</option>`).join("");
  fillPc();
}
function fillPc(){
  const pcs = st.site==="all"? [...new Set(D.sites.flatMap(s=>s.pcs))] : D.sites.find(s=>s.id===st.site).pcs;
  if(st.pc!=="all"&&!pcs.includes(st.pc)) st.pc="all";
  $("#fPc").innerHTML='<option value="all">All profit centres</option>'+pcs.map(p=>`<option>${esc(p)}</option>`).join("");
  $("#fPc").value=st.pc;
}

/* ---------- aggregates ---------- */
function agg(rows){
  const rev=sum(rows,r=>r.rev), cogs=sum(rows,r=>r.cogs), opex=sum(rows,r=>r.opex), budget=sum(rows,r=>r.budget);
  const quotes=sum(rows,r=>r.quotes), q30=sum(rows,r=>r.quotes_30), orders=sum(rows,r=>r.orders), cash=sum(rows,r=>r.cash);
  const last=D.months.slice(-1)[0]; const recv=sum(rows.filter(r=>r.m===months().slice(-1)[0]),r=>r.recv);
  const days=st.per*30.4; const gm=rev-cogs;
  return {rev,cogs,opex,budget,gm,gmp:rev?gm/rev:0,contrib:gm-opex,cp:rev?(gm-opex)/rev:0,var:rev-budget,varp:budget?(rev-budget)/budget:0,
    quotes,q30,sla:quotes?q30/quotes:0,orders,conv:quotes?orders/quotes:0,cash,coll:rev?cash/rev:0,recv,dso:rev?recv/(rev/days):0,last};
}
function delta(cur,prev,better){ if(!prev) return '<span class="flat">no earlier period</span>';
  const d=(cur-prev)/Math.abs(prev); const good = better==="lower"? d<0 : d>0;
  return `<span class="${Math.abs(d)<0.005?"flat":good?"up":"down"}">${d>=0?"▲":"▼"} ${Math.abs(d*100).toFixed(1)}% vs previous ${st.per} mo</span>`;}

/* ---------- charts (inline SVG, one scale per chart) ---------- */
function niceMax(v){if(v<=0)return 1;const p=Math.pow(10,Math.floor(Math.log10(v)));const n=v/p;return (n<=1?1:n<=2?2:n<=5?5:10)*p}
function comboChart(labels,bars,line,opts){
  const W=640,H=230,L=58,R=12,T=12,B=28,w=W-L-R,h=H-T-B; const mx=niceMax(Math.max(...bars,...line));
  const bw=w/labels.length; const y=v=>T+h-v/mx*h; let g="";
  for(let i=0;i<=4;i++){const v=mx*i/4;g+=`<line class="gl" x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}"/><text x="${L-6}" y="${y(v)+4}" text-anchor="end">${money(v)}</text>`}
  bars.forEach((v,i)=>{g+=`<rect x="${L+i*bw+bw*.18}" y="${y(v)}" width="${bw*.64}" height="${T+h-y(v)}" fill="var(--c1)" rx="2"><title>${labels[i]}: ${money(v)}</title></rect>`;
    g+=`<text x="${L+i*bw+bw/2}" y="${H-10}" text-anchor="middle">${labels[i].slice(2)}</text>`});
  const pts=line.map((v,i)=>`${L+i*bw+bw/2},${y(v)}`).join(" ");
  g+=`<polyline points="${pts}" fill="none" stroke="var(--c4)" stroke-width="2" stroke-dasharray="5 3"/>`;
  line.forEach((v,i)=>g+=`<circle cx="${L+i*bw+bw/2}" cy="${y(v)}" r="3" fill="var(--c4)"><title>${opts.lineName} ${labels[i]}: ${money(v)}</title></circle>`);
  return `<svg viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="${opts.aria}">${g}</svg><div class="legend"><span><i data-s="background:var(--c1)"></i>${opts.barName}</span><span><i data-s="background:var(--c4)"></i>${opts.lineName}</span></div>`;
}
function hbars(items,fmt,color){
  const mx=Math.max(...items.map(i=>Math.abs(i.v)),1);
  return `<div data-s="display:grid;gap:6px">`+items.map(i=>`<div data-s="display:grid;grid-template-columns:minmax(0,9rem) minmax(0,1fr) 5.5rem;gap:8px;align-items:center">
   <span data-s="overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${esc(i.k)}">${esc(i.k)}</span>
   <span data-s="background:var(--accent-soft);border-radius:3px;height:14px;position:relative"><span class="bar" data-s="position:absolute;inset:0 auto 0 0;width:${Math.abs(i.v)/mx*100}%;background:${i.v<0?"var(--bad)":(i.c||color||"var(--c1)")};border-radius:3px"></span></span>
   <span data-s="text-align:right;font-family:var(--f-num);font-size:.78rem">${fmt(i.v)}</span></div>`).join("")+`</div>`;
}
function spark(series,better,target){
  const W=110,H=30,mx=Math.max(...series,target)*1.05,mn=Math.min(...series,target)*0.95; const x=i=>4+i*(W-8)/(series.length-1); const y=v=>H-3-(v-mn)/((mx-mn)||1)*(H-6);
  const p=series.map((v,i)=>`${x(i)},${y(v)}`).join(" ");
  return `<svg viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" aria-hidden="true"><line x1="0" x2="${W}" y1="${y(target)}" y2="${y(target)}" stroke="var(--mut)" stroke-dasharray="2 2"/><polyline points="${p}" fill="none" stroke="var(--c1)" stroke-width="1.6"/><circle cx="${x(series.length-1)}" cy="${y(series.at(-1))}" r="2.6" fill="var(--c1)"/></svg>`;
}
function lineChart(labels,series,opts){
  const W=640,H=220,L=48,R=12,T=12,B=28,w=W-L-R,h=H-T-B; const mx=niceMax(Math.max(...series.flatMap(s=>s.v))*1.05);
  const x=i=>L+i*w/(labels.length-1), y=v=>T+h-v/mx*h; let g="";
  for(let i=0;i<=4;i++){const v=mx*i/4;g+=`<line class="gl" x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}"/><text x="${L-6}" y="${y(v)+4}" text-anchor="end">${opts.fmt(v)}</text>`}
  labels.forEach((l,i)=>g+=`<text x="${x(i)}" y="${H-10}" text-anchor="middle">${l}</text>`);
  series.forEach(s=>{g+=`<polyline points="${s.v.map((v,i)=>x(i)+","+y(v)).join(" ")}" fill="none" stroke="${s.c}" stroke-width="2"/>`;
    s.v.forEach((v,i)=>g+=`<circle cx="${x(i)}" cy="${y(v)}" r="2.6" fill="${s.c}"><title>${s.n} ${labels[i]}: ${opts.fmt(v)}</title></circle>`)});
  return `<svg viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="${opts.aria}">${g}</svg><div class="legend">${series.map(s=>`<span><i data-s="background:${s.c}"></i>${s.n}</span>`).join("")}</div>`;
}
function table(id,head,rows,foot){
  return `<div class="tbl"><table id="${id}"${id==="tGap"||id.startsWith("tK")?' class="left"':""}><thead><tr>${head.map(h=>`<th title="${esc(h.f?FX[h.f]:h.t)}">${esc(h.t)}</th>`).join("")}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join("")}</tr>`).join("")}</tbody>${foot?`<tfoot><tr class="total">${foot.map(c=>`<td>${c}</td>`).join("")}</tr></tfoot>`:""}</table></div>
  <div class="row" data-s="margin-top:8px"><button type="button" data-copy="${id}">Copy table (CSV)</button><span class="note">Hover a column title to see its formula.</span></div>`;
}
function rag(actual,target,better){const r=better==="lower"? target/(actual||1e-9) : actual/(target||1e-9); return r>=1?"g":r>=0.9?"a":"r";}
const ragTxt={g:"On track",a:"Watch",r:"Act now"};

/* ---------- views ---------- */
const V={};
V.overview=()=>{
  const a=agg(facts()), p=agg(facts(prevMonths()));
  const dl=deals(); const open=dl.filter(d=>!["Won","Lost"].includes(d.stage));
  const wp=sum(open,d=>d.amount*D.stages.find(s=>s.name===d.stage).p);
  const won=dl.filter(d=>d.stage==="Won").length, lost=dl.filter(d=>d.stage==="Lost").length;
  const tiles=[["Revenue",money(a.rev),delta(a.rev,p.rev),"rev"],["Gross margin %",pct(a.gmp),delta(a.gmp,p.gmp),"gmp"],["Contribution",money(a.contrib),delta(a.contrib,p.contrib),"contrib"],
    ["Budget variance",money(a.var),`<span class="${a.var>=0?"up":"down"}">${pct(a.varp)} vs budget</span>`,"varp"],["Quotes in 30 min",pct(a.sla),delta(a.sla,p.sla),"sla"],
    ["Days sales outstanding",a.dso.toFixed(0)+" days",delta(a.dso,p.dso,"lower"),"dso"],["Weighted pipeline",money(wp),`<span class="flat">${open.length} open deals</span>`,"wp"],["Win rate",pct(won/((won+lost)||1)),`<span class="flat">${won} won · ${lost} lost</span>`,"win"]];
  const ms=months(); const byM=ms.map(m=>agg(facts([m])));
  const bySite=D.sites.filter(s=>st.site==="all"||s.id===st.site).map(s=>{const r=D.facts.filter(f=>f.site===s.id&&ms.includes(f.m)&&(st.pc==="all"||f.pc===st.pc));const x=agg(r);return {k:s.name,v:x.rev,gmp:x.gmp,c:"var(--c1)"}});
  const alerts=[];
  if(a.sla<0.9)alerts.push(["a",`Only ${pct(a.sla)} of quotes went out within 30 minutes. Goal is 90%.`]);
  if(a.varp<0)alerts.push(["r",`Revenue is ${pct(-a.varp)} below budget.`]);
  if(a.dso>45)alerts.push(["a",`Customers take ${a.dso.toFixed(0)} days to pay. Goal is 45 days or less.`]);
  const stale=open.filter(d=>d.age>90).length; if(stale)alerts.push(["a",`${stale} open deals are older than 90 days.`]);
  if(!alerts.length)alerts.push(["g","All headline measures are on track."]);
  return `<div class="tiles">${tiles.map(t=>`<div class="tile" title="${esc(FX[t[3]])}"><span class="k">${t[0]}</span><span class="v">${t[1]}</span><span class="d">${t[2]}</span></div>`).join("")}</div>
  <section class="p w8"><h2>Revenue by month against budget</h2><p class="sub">${st.site==="all"?"All sites on this side":esc(siteName(st.site))} · ${st.pc==="all"?"all profit centres":esc(st.pc)}</p>${comboChart(ms,byM.map(x=>x.rev),byM.map(x=>x.budget),{barName:"Revenue",lineName:"Budget",aria:"Revenue by month with budget line"})}</section>
  <section class="p w4"><h2>What needs attention</h2><p class="sub">Rules run on the filters above</p><div data-s="display:grid;gap:8px">${alerts.map(x=>`<div><span class="pill ${x[0]}">${ragTxt[x[0]]}</span> ${esc(x[1])}</div>`).join("")}</div></section>
  <section class="p w12"><h2>Revenue by site</h2><p class="sub">Pick a site in the Site filter to drill in</p>${hbars(bySite,money)}</section>`;
};
V.profit=()=>{
  const ms=months(); const rows=[]; const all=[];
  D.sites.filter(s=>st.site==="all"||s.id===st.site).forEach(s=>s.pcs.filter(p=>st.pc==="all"||p===st.pc).forEach(pc=>{
    const r=D.facts.filter(f=>f.site===s.id&&f.pc===pc&&ms.includes(f.m)); all.push(...r); const a=agg(r);
    rows.push({s:s.name,pc,a});}));
  rows.sort((x,y)=>y.a.contrib-x.a.contrib);
  const T=agg(all);
  const cells=x=>[money(x.rev),money(x.cogs),money(x.gm),pct(x.gmp),money(x.opex),money(x.contrib),pct(x.cp),money(x.budget),`<span class="${x.var>=0?"up":"down"}">${money(x.var)}</span>`,`<span class="pill ${x.varp>=0?"g":x.varp>-0.1?"a":"r"}">${pct(x.varp)}</span>`,pct(x.coll)];
  const head=[{t:"Site · profit centre"},{t:"Revenue",f:"rev"},{t:"Cost of sales"},{t:"Gross margin",f:"gm"},{t:"GM %",f:"gmp"},{t:"Direct cost"},{t:"Contribution",f:"contrib"},{t:"Contrib %",f:"cp"},{t:"Budget",f:"bud"},{t:"Variance",f:"var"},{t:"Var %",f:"varp"},{t:"Collected",f:"coll"}];
  return `<section class="p w12"><h2>Profit-centre statement</h2><p class="sub">Last ${st.per} months · sorted by contribution · every figure is worked out from the order and cost records</p>
  ${table("tPc",head,rows.map(r=>[esc(r.s+" · "+r.pc),...cells(r.a)]),["Total",...cells(T)])}</section>
  <section class="p"><h2>Contribution by profit centre</h2><p class="sub">${esc(FX.contrib)}</p>${hbars(rows.map(r=>({k:r.pc+(st.site==="all"?" ("+r.s+")":""),v:r.a.contrib})),money,"var(--c2)")}</section>
  <section class="p"><h2>Gross margin % by profit centre</h2><p class="sub">${esc(FX.gmp)}</p>${hbars(rows.map(r=>({k:r.pc+(st.site==="all"?" ("+r.s+")":""),v:r.a.gmp})),pct,"var(--c3)")}</section>`;
};
V.pipeline=()=>{
  const dl=deals(); const mult=st.prob/100;
  const P=n=>Math.min(1,D.stages.find(s=>s.name===n).p*(n==="Won"?1:mult));
  const by=D.stages.map(s=>{const x=dl.filter(d=>d.stage===s.name);return {s:s.name,p:P(s.name),n:x.length,v:sum(x,d=>d.amount),w:sum(x,d=>d.amount*P(s.name))}});
  const open=by.filter(b=>!["Won","Lost"].includes(b.s)); const won=by.find(b=>b.s==="Won"), lost=by.find(b=>b.s==="Lost");
  const qs=[["Q4 2026",["2026-11","2026-12"]],["Q1 2027",["2027-01","2027-02","2027-03"]]];
  const fc=qs.map(([q,ms])=>{const x=dl.filter(d=>ms.includes(d.close));const w=x.filter(d=>d.stage==="Won"),n=x.filter(d=>d.stage==="Negotiation"),pr=x.filter(d=>d.stage==="Proposal");
    const commit=sum(w,d=>d.amount)+sum(n,d=>d.amount); const best=commit+sum(pr,d=>d.amount); const pipe=sum(x.filter(d=>d.stage!=="Lost"),d=>d.amount); const weighted=sum(x,d=>d.amount*P(d.stage));
    return [q,money(sum(w,d=>d.amount)),money(commit),money(best),money(pipe),money(weighted)]});
  const ms3=D.months.slice(-3); const target=sum(D.facts.filter(f=>(st.site==="all"||f.site===st.site)&&(st.pc==="all"||f.pc===st.pc)&&ms3.includes(f.m)),f=>f.budget)*1.05;
  const openV=sum(open,b=>b.v); const cov=openV/Math.max(1,target-won.v);
  const aging=[["0-30 days",0,30],["31-60 days",31,60],["61-90 days",61,90],["Over 90 days",91,999]].map(([k,a,b])=>({k,v:sum(dl.filter(d=>!["Won","Lost"].includes(d.stage)&&d.age>=a&&d.age<=b),d=>d.amount),c:b>90?"var(--warn)":"var(--c5)"}));
  const srcs=[...new Set(dl.map(d=>d.source))].map(s=>{const x=dl.filter(d=>d.source===s);const w=x.filter(d=>d.stage==="Won").length,l=x.filter(d=>d.stage==="Lost").length;return {k:s,v:w/((w+l)||1)}});
  const top=dl.filter(d=>!["Won","Lost"].includes(d.stage)).sort((a,b)=>b.amount*P(b.stage)-a.amount*P(a.stage)).slice(0,10);
  return `<div class="tiles">
   <div class="tile" title="${esc(FX.wp)}"><span class="k">Weighted pipeline</span><span class="v">${money(sum(open,b=>b.w))}</span><span class="d flat">${sum(open,b=>b.n)} open deals</span></div>
   <div class="tile" title="${esc(FX.win)}"><span class="k">Win rate</span><span class="v">${pct(won.n/((won.n+lost.n)||1))}</span><span class="d flat">${won.n} won · ${lost.n} lost</span></div>
   <div class="tile" title="${esc(FX.cov)}"><span class="k">Pipeline coverage</span><span class="v">${cov.toFixed(1)}x</span><span class="d ${cov>=3?"up":"down"}">${cov>=3?"Healthy (3x or more)":"Below 3x: add pipeline"}</span></div>
   <div class="tile"><span class="k">Average deal</span><span class="v">${money(sum(by,b=>b.v)/(dl.length||1))}</span><span class="d flat">${dl.length} deals in view</span></div></div>
  <section class="p"><h2>Pipeline by stage</h2><p class="sub">Value and weighted value (value x probability)</p>
   ${table("tStage",[{t:"Stage"},{t:"Probability"},{t:"Deals"},{t:"Value"},{t:"Weighted",f:"wp"}],by.map(b=>[b.s,pct(b.p),b.n,money(b.v),money(b.w)]))}
   <div class="row" data-s="margin-top:10px"><label for="prob" class="note">What-if: stage probabilities at <b id="probV">${st.prob}%</b></label><input id="prob" type="range" min="50" max="150" step="5" value="${st.prob}"></div></section>
  <section class="p"><h2>Funnel</h2><p class="sub">Open value at each stage</p>${hbars(by.filter(b=>b.s!=="Lost").map((b,i)=>({k:b.s,v:b.v,c:`var(--c${i+1})`})),money)}</section>
  <section class="p w12"><h2>Forecast by quarter</h2><p class="sub">${esc(FX.commit)} · ${esc(FX.best)}</p>${table("tFc",[{t:"Quarter"},{t:"Won"},{t:"Commit",f:"commit"},{t:"Best case",f:"best"},{t:"All open + won"},{t:"Weighted",f:"wp"}],fc)}</section>
  <section class="p"><h2>Deal ageing (open deals)</h2><p class="sub">Deals over 90 days need a decision: move forward or close as lost</p>${hbars(aging,money)}</section>
  <section class="p"><h2>Win rate by lead source</h2><p class="sub">${esc(FX.win)}</p>${hbars(srcs,pct,"var(--c2)")}</section>
  <section class="p w12"><h2>Top 10 open deals by weighted value</h2><p class="sub">Demo accounts only</p>${table("tTop",[{t:"Deal"},{t:"Account"},{t:"Site"},{t:"Profit centre"},{t:"Stage"},{t:"Value"},{t:"Weighted",f:"wp"},{t:"Close"},{t:"Age (days)"},{t:"Country"}],
    top.map(d=>[d.id,esc(d.account),esc(siteName(d.site)),esc(d.pc),d.stage,money(d.amount),money(d.amount*P(d.stage)),d.close,d.age>90?`<span class="pill a">${d.age}</span>`:d.age,esc(d.country)]))}</section>`;
};
V.market=()=>{
  const m=mkt(); const size=sum(m,x=>x.size), ours=sum(m,x=>x.size*x.ours);
  const comp=[0,1,2,3,4].map(i=>sum(m,x=>x.size*x.comp[i])); const others=sum(m,x=>x.size*x.others);
  const lostM=sum(m.filter(x=>x.offered),x=>x.size*(1-x.ours)), nonM=sum(m.filter(x=>!x.offered),x=>x.size);
  const tgt=0.10*lostM+0.05*nonM; const topC=Math.max(...comp);
  const segs=[...new Set(m.map(x=>x.segment))];
  const segRows=segs.map(sg=>{const x=m.filter(y=>y.segment===sg);const sz=sum(x,y=>y.size),o=sum(x,y=>y.size*y.ours);const l=sum(x.filter(y=>y.offered),y=>y.size*(1-y.ours)),n=sum(x.filter(y=>!y.offered),y=>y.size);
    const g=sum(x,y=>y.size*y.growth)/sz;const pi=sum(x,y=>y.size*y.price_index)/sz;
    return [esc(sg),money(sz),`<span class="${g>=0?"up":"down"}">${pct(g)}</span>`,money(o),pct(o/sz),pi.toFixed(1),money(l),money(n),money(0.1*l+0.05*n)]});
  const names=["Competitor A","Competitor B","Competitor C","Competitor D","Competitor E"];
  const shareItems=[{k:"Us",v:ours/size,c:"var(--c2)"},...names.map((n,i)=>({k:n,v:comp[i]/size,c:"var(--c6)"})),{k:"All others",v:others/size,c:"var(--c6)"}].sort((a,b)=>b.v-a.v);
  const qs=[...new Set(D.share_trend.map(t=>t.q))]; const tr=D.share_trend.filter(t=>st.site==="all"||t.site===st.site);
  const qv=qs.map(q=>{const x=tr.filter(t=>t.q===q);return {o:sum(x,t=>t.ours)/x.length,t:sum(x,t=>t.top)/x.length}});
  const cells=m.map(x=>[esc(x.segment),esc(x.country),x.offered?'<span class="pill g">Offered</span>':'<span class="pill a">Not offered</span>',money(x.size),pct(x.ours),pct(Math.max(...x.comp)),x.price_index.toFixed(1),`<span class="${x.growth>=0?"up":"down"}">${pct(x.growth)}</span>`]);
  return `<div class="tiles t3">
   <div class="tile" title="${esc(FX.share)}"><span class="k">Market size (yearly)</span><span class="v">${money(size)}</span><span class="d flat">${segs.length} segments · ${st.country==="all"?D.countries.length+" countries":esc(st.country)}</span></div>
   <div class="tile" title="${esc(FX.share)}"><span class="k">Our share</span><span class="v">${pct(ours/size)}</span><span class="d flat">${money(ours)} sales</span></div>
   <div class="tile" title="${esc(FX.rel)}"><span class="k">Relative share</span><span class="v">${(ours/topC).toFixed(2)}x</span><span class="d flat">vs largest competitor</span></div>
   <div class="tile" title="${esc(FX.lost)}"><span class="k">Lost market</span><span class="v">${money(lostM)}</span><span class="d flat">lines we offer</span></div>
   <div class="tile" title="${esc(FX.non)}"><span class="k">Non-offered market</span><span class="v">${money(nonM)}</span><span class="d flat">lines to add</span></div>
   <div class="tile" title="${esc(FX.tgt)}"><span class="k">Draft growth target</span><span class="v">${money(tgt)}</span><span class="d flat">10% lost + 5% non-offered</span></div></div>
  <section class="p"><h2>Share of market</h2><p class="sub">Competitors are anonymised (A to E). Demo figures.</p>${hbars(shareItems,pct)}</section>
  <section class="p"><h2>Share trend, 8 quarters</h2><p class="sub">Us against the largest competitor</p>${lineChart(qs.map(q=>q.replace("20","").replace("-"," ")),[{n:"Us",c:"var(--c2)",v:qv.map(x=>x.o)},{n:"Largest competitor",c:"var(--c6)",v:qv.map(x=>x.t)}],{fmt:v=>(v*100).toFixed(0)+"%",aria:"Market share trend"})}</section>
  <section class="p w12"><h2>Segment view with gap and draft target</h2><p class="sub">${esc(FX.tgt)}</p>${table("tSeg",[{t:"Segment"},{t:"Market size"},{t:"Market growth"},{t:"Our sales"},{t:"Our share",f:"share"},{t:"Price index",f:"pidx"},{t:"Lost market",f:"lost"},{t:"Non-offered",f:"non"},{t:"Draft target",f:"tgt"}],segRows)}</section>
  <section class="p w12"><h2>Segment by country</h2><p class="sub">One row per segment and country. Use the Country filter to focus.</p>${table("tMkt",[{t:"Segment"},{t:"Country"},{t:"Status"},{t:"Market size"},{t:"Our share",f:"share"},{t:"Largest competitor"},{t:"Price index",f:"pidx"},{t:"Growth"}],cells)}</section>`;
};
V.outcomes=()=>{
  const k=D.kpis.filter(x=>st.site==="all"||x.site===st.site);
  const persps=[...new Set(k.map(x=>x.perspective))];
  const groups=persps.map(p=>{const x=k.filter(y=>y.perspective===p);
    const names=[...new Set(x.map(y=>y.name))];
    const rows=names.map(n=>{const y=x.filter(z=>z.name===n);const ser=y[0].series.map((_,i)=>sum(y,z=>z.series[i])/y.length);const a=ser.at(-1);const r=rag(a,y[0].target,y[0].better);
      return {n,r,html:[esc(n),`${y[0].target}${y[0].unit==="%"?"%":" "+y[0].unit}`,`${a.toFixed(1)}${y[0].unit==="%"?"%":" "+y[0].unit}`,`<span class="pill ${r}">${ragTxt[r]}</span>`,spark(ser,y[0].better,y[0].target),esc(y[0].owner),`<span class="formula">${esc(y[0].formula)}</span>`]}});
    return {p,rows}});
  const all=groups.flatMap(g=>g.rows); const c={g:0,a:0,r:0}; all.forEach(r=>c[r.r]++);
  return `<div class="tiles t3"><div class="tile"><span class="k">Outcomes on track</span><span class="v up">${c.g}</span><span class="d flat">of ${all.length} measures</span></div>
  <div class="tile"><span class="k">Watch</span><span class="v" data-s="color:var(--warn)">${c.a}</span><span class="d flat">within 10% of target</span></div>
  <div class="tile"><span class="k">Act now</span><span class="v down">${c.r}</span><span class="d flat">more than 10% off</span></div></div>
  ${groups.map((g,i)=>`<section class="p w12"><h2>${esc(g.p)}</h2><p class="sub">Last 6 months · dashed line = target · ${esc(FX.rag)}</p>${table("tK"+i,[{t:"Measure"},{t:"Target"},{t:"Latest"},{t:"Status",f:"rag"},{t:"Trend"},{t:"Owner role"},{t:"Formula"}],g.rows.map(r=>r.html))}</section>`).join("")}`;
};
V.formulas=()=>`<section class="p w12"><h2>Every formula used on this desk</h2><p class="sub">The same formulas run for every site and profit centre, so numbers can be compared.</p>
  <dl class="fx">${Object.entries(FX).map(([k,v])=>{const i=v.indexOf(" = ");return `<dt>${esc(i>0?v.slice(0,i):k)}</dt><dd><span class="formula">${esc(i>0?v.slice(i+3):v)}</span></dd>`}).join("")}</dl></section>
  <section class="p w12"><h2>Where the numbers come from</h2><ol class="gaps">
  <li><b>ERP</b>: orders, invoices, cost of sales, cash received, receivables (month by profit centre).</li>
  <li><b>CRM</b>: deals, stages, values, close months, lead sources.</li>
  <li><b>MIS</b>: quote times, on-time delivery, customer scores, SOP reviews, learning hours.</li>
  <li><b>Market intelligence</b>: market size by segment and country, anonymised competitor shares, price index, growth.</li></ol>
  <p class="note">Today these are demo records made from a fixed seed. When the live order desk is switched on, the same fields are filled from real orders and the formulas stay the same.</p></section>`;
V.gaps=()=>`<section class="p w12"><h2>Gaps against leading CRM and ERP suites</h2><p class="sub">What the order desk and staff office already do, and what this desk adds or still needs</p>
 ${table("tGap",[{t:"Area"},{t:"Before this desk"},{t:"Now"},{t:"Still needed"}],[
  ["Dashboards with drill-down","Order list only","Site, profit centre, country, period filters","Saved views per role"],
  ["Profit-centre P&amp;L","Not built","Revenue, margin, contribution, budget variance","Real cost allocation rules from finance"],
  ["Pipeline and forecast","Quote status only","Stages, weighted pipeline, commit / best case, coverage, ageing","Live deal entry screen"],
  ["Market intelligence","Separate pages","Share, relative share, lost and non-offered market, draft targets","Real market sizes from country files (restricted)"],
  ["Management outcomes","Not built","Scorecard in 4 perspectives with RAG and owner role","Targets agreed by owner"],
  ["Formulas visible","No","Every column shows its formula","-"],
  ["Data export","No","Copy any table as CSV","Scheduled export to shared drive"],
  ["Alerts","SLA timer only","Rules: SLA, budget, DSO, stale deals","Daily email digest (needs yes mail)"],
  ["Role-based access","Staff sign-in","Staff-only page, demo data","Per-role row filters"],
  ["Data from live orders","Demo orders","Demo facts","Nightly job from the order database"]].map(r=>r))}</section>`;

/* ---------- wiring ---------- */
function render(){
  const v=(location.hash||"#overview").slice(1); const view=V[v]?v:"overview";
  document.querySelectorAll("#tabs a").forEach(a=>{if(a.dataset.v===view)a.setAttribute("aria-current","page");else a.removeAttribute("aria-current")});
  $("#view").innerHTML=V[view]();
  const pr=$("#prob"); if(pr) pr.addEventListener("input",e=>{st.prob=+e.target.value;render()});
}
document.addEventListener("click",e=>{const b=e.target.closest("[data-copy]");if(!b)return;
  const t=document.getElementById(b.dataset.copy);const csv=[...t.querySelectorAll("tr")].map(r=>[...r.children].map(c=>'"'+c.innerText.replace(/"/g,'""')+'"').join(",")).join("\n");
  Promise.resolve().then(()=>navigator.clipboard.writeText(csv)).then(()=>toast("Table copied as CSV"),()=>{const ta=document.createElement("textarea");ta.value=csv;document.body.append(ta);ta.select();try{document.execCommand("copy")}catch(x){}ta.remove();toast("Table copied as CSV")});});
["fSite","fPc","fCountry","fPer"].forEach(id=>$("#"+id).addEventListener("change",e=>{
  const k={fSite:"site",fPc:"pc",fCountry:"country",fPer:"per"}[id]; st[k]=k==="per"?+e.target.value:e.target.value; if(k==="site")fillPc(); store(k,st[k]); render();}));
function setTheme(t){document.documentElement.setAttribute("data-theme",t);$("#theme").textContent=t==="dark"?"Light":"Dark";store("theme",t)}
$("#theme").addEventListener("click",()=>setTheme(document.documentElement.getAttribute("data-theme")==="dark"?"light":"dark"));
window.addEventListener("hashchange",render);
$("#tabs").addEventListener("click",e=>{const a=e.target.closest("a[data-v]");if(!a)return;e.preventDefault();if(location.hash!=="#"+a.dataset.v){history.replaceState(null,"","#"+a.dataset.v)}render()});
fillFilters();
["site","country"].forEach(k=>{const v=load(k);if(v&&[...$(k==="site"?"#fSite":"#fCountry").options].some(o=>o.value===v)){st[k]=v;$(k==="site"?"#fSite":"#fCountry").value=v}});
fillPc();
setTheme(load("theme")||"light");
render();
